/**
 * The edge's package verification held to the engine's, vector by vector:
 * docs/plugin-package-vectors.json is generated by the engine lane from the
 * engine's own code (crates/engine/src/plugins/vectors.rs), and every case
 * runs here. (Tests only: nothing at runtime imports the file.)
 */
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { isText } from "./checks";
import { consentItem, contained, fullControlNames, heldNames, windowsExtensions } from "./consent";
import { JsonError, type JsonObject, canonicalJson, compareUtf8, isObject, parseJsonText } from "./json";
import {
  changelogNotes,
  checkListing,
  checkTemplate,
  listingOf,
  listingOfTemplate
} from "./listing";
import { idProblem, readManifest } from "./manifest";
import { MAX_MANIFEST_JSON, MAX_MANIFEST_VALUES, PackageRefusal, checkSignature, contentHash, signaturePayload, verifyPackage, verifyTemplate } from "./package";
import { MAX_PUBLISH_BODY_BYTES } from "./identity/body";
import { plainPath } from "./paths";
import { crc32, deployTokenHash, parseDeployToken, readScopeIds, tokenChecksum, tokenFromBody } from "./identity/deploy-token";
import { comparePrecedence, parseRange, parseVersion, satisfies } from "./semver";
import { STORE_DATA } from "./data";

/* eslint-disable @typescript-eslint/no-explicit-any */
const fromB64 = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, "base64"));
const here = dirname(fileURLToPath(import.meta.url));
/** `{ parts: [...] }` written for a long string: its parts joined, each a
 * string or `{ repeat, count }` (the vectors' `about` says so). */
const joinParts = (parts: any[]): string => parts.map((p: any) => (typeof p === "string" ? p : String(p.repeat).repeat(p.count))).join("");
const expand = (value: any): any => {
  if (Array.isArray(value)) return value.map(expand);
  if (value && typeof value === "object") {
    const keys = Object.keys(value);
    if (keys.length === 1 && keys[0] === "parts" && Array.isArray(value.parts)) {
      return joinParts(value.parts);
    }
    return Object.fromEntries(keys.map((k) => [k, expand(value[k])]));
  }
  return value;
};
const rawVectors: any = JSON.parse(readFileSync(resolve(here, "../../../docs/plugin-package-vectors.json"), "utf8"));
const v: any = expand(JSON.parse(readFileSync(resolve(here, "../../../docs/plugin-package-vectors.json"), "utf8")));
/** A `files_b64` value: base64, or (written as parts) its text's UTF-8 bytes. */
const fileBytes = (raw: unknown, written: unknown): Uint8Array => {
  if (written && typeof written === "object" && Array.isArray((written as { bytes?: unknown }).bytes)) {
    // `{ bytes: [...] }`: the parts' bytes one after another, each a base64
    // string or `{ repeat, count }`.
    return new Uint8Array(Buffer.concat((written as { bytes: (string | { repeat: string; count: number })[] }).bytes.map((p) => (typeof p === "string" ? Buffer.from(p, "base64") : Buffer.from(p.repeat.repeat(p.count))))));
  }
  return written && typeof written === "object" ? new TextEncoder().encode(raw as string) : fromB64(raw as string);
};


const hashesOf = (files: Record<string, string>) => new Map(Object.entries(files));
/** A manifest given as JSON text (so number spellings survive), or a value. */
const json = (m: unknown) => (typeof m === "string" ? parseJsonText(m) : parseJsonText(JSON.stringify(m)));

describe("engine vectors (docs/plugin-package-vectors.json)", () => {
  it("is the file the engine makes, beside its data file", () => {
    expect(v.format).toBe("zeron-plugin-package-vectors:v1");
    expect([STORE_DATA.format, STORE_DATA.package_format, STORE_DATA.payload_prefix]).toEqual(["zeron-plugin-store-data:v1", "zeron-plugin:v1", "zeron-plugin:v1\n"]);
  });

  it("the store's own measured bounds are the data file's", () => {
    // (Kept as constants where they're used, and held to the file here: a
    // different value in the engine's next file fails this.)
    expect([MAX_PUBLISH_BODY_BYTES, MAX_MANIFEST_JSON, MAX_MANIFEST_VALUES]).toEqual([
      STORE_DATA.limits.max_publish_body_bytes,
      STORE_DATA.limits.max_manifest_json_bytes,
      STORE_DATA.limits.max_manifest_values
    ]);
  });

  it("canonical JSON", () => {
    for (const c of v.canonical_json) {
      if (c.error) expect(() => parseJsonText(c.input), c.name).toThrow(JsonError);
      else expect(canonicalJson(parseJsonText(c.input)), c.name).toBe(c.canonical);
    }
  });

  it("content hashes", async () => {
    for (const c of v.content_hash) {
      const files = typeof c.files === "string" ? JSON.parse(c.files) : c.files;
      expect(await contentHash(json(c.manifest) as JsonObject, hashesOf(files)), c.name).toBe(c.hash);
    }
  });

  it("signatures", async () => {
    for (const c of v.signatures) {
      const manifest = json(c.manifest);
      const files = hashesOf(c.files);
      if (c.payload && c.key && isObject(manifest)) expect(signaturePayload(c.prefix, manifest, c.key, files), c.name).toBe(c.payload);
      const checked = await checkSignature(c.prefix, manifest, files);
      expect("valid" in checked ? "valid" : checked.invalid, c.name).toBe(c.result);
    }
  });

  it("packages", async () => {
    for (const [i, c] of v.packages.entries()) {
      let got: unknown;
      try {
        // (`package_parts`: the package's text, in parts; its UTF-8 bytes.)
        const raw = c.package_parts !== undefined ? new TextEncoder().encode(joinParts(rawVectors.packages[i].package_parts)) : fromB64(c.package_b64);
        const p = await verifyPackage(raw);
        // (`paths`: the engine's BTreeMap order, its keys' UTF-8 bytes.)
        got = { ok: true, id: p.manifest.id, version: p.manifest.version, key: p.key, hash: p.hash, sha256: p.sha256, files: p.files.size, paths: [...p.files.keys()].sort(compareUtf8) };
      } catch (e) {
        if (!(e instanceof PackageRefusal)) throw e;
        got = { ok: false, error: e.code };
      }
      expect(got, c.name).toEqual(c.result);
    }
  });

  it("store packages: a deploy token's is unsigned only, its content hash a signed one's", async () => {
    const read = async (raw: Uint8Array, signed: boolean) => {
      try {
        const p = await verifyPackage(raw, undefined, signed);
        return { ok: true, id: p.manifest.id, version: p.manifest.version, key: p.key, hash: p.hash, sha256: p.sha256, files: p.files.size, paths: [...p.files.keys()].sort(compareUtf8) };
      } catch (e) {
        if (!(e instanceof PackageRefusal)) throw e;
        return { ok: false, error: e.code };
      }
    };
    expect(v.store_packages.length).toBeGreaterThan(0);
    // Each as the store reads a deploy token's publish, the record a device
    // then reads naming no key: unsigned only. Where a device refuses a
    // signed one (`store_mismatch`, or `tampered` before it), the store
    // refuses it first, as its publish says it: `bad_signature`.
    for (const c of v.store_packages) {
      const raw = fromB64(c.package_b64);
      const signed = JSON.parse(new TextDecoder().decode(raw)).manifest?.signature !== undefined;
      const got = await read(raw, false);
      if (signed) {
        expect(c.result.ok, c.name).toBe(false);
        expect(got, c.name).toEqual({ ok: false, error: "bad_signature" });
      } else {
        expect(got, c.name).toEqual(c.result);
      }
    }
    // Its content hash is a signed package's of the same files, as a device
    // computes it: the refused signed one, read as a device's own publish.
    const unsigned = v.store_packages.find((c: any) => c.result.ok);
    const mismatch = v.store_packages.find((c: any) => c.result.error === "store_mismatch");
    const asSigned = await read(fromB64(mismatch.package_b64), true);
    expect(asSigned).toMatchObject({ ok: true, hash: unsigned.result.hash, id: unsigned.result.id, version: unsigned.result.version });
  });

  it("deploy tokens: the format, from the data file", () => {
    const format = STORE_DATA.deploy_token;
    expect(format).toMatchObject({ prefix: v.deploy_token.prefix, alphabet: v.deploy_token.alphabet, body_len: v.deploy_token.body_len, check_len: v.deploy_token.check_len, len: v.deploy_token.len, short_len: v.deploy_token.short_len });
    expect([...format.alphabet].sort().join("")).toBe([..."0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"].sort().join(""));
    expect(format.prefix.length + format.body_len + format.check_len).toBe(format.len);
  });

  it("deploy tokens: each fixed token, its body, checksum, short id and hash", async () => {
    expect(v.deploy_token.tokens.length).toBeGreaterThan(0);
    for (const c of v.deploy_token.tokens) {
      // The body is the random bytes as one big-endian integer in base62.
      const n = BigInt(`0x${c.random_hex}`);
      let body = "";
      for (let rest = n; rest > 0n; rest /= 62n) body = v.deploy_token.alphabet[Number(rest % 62n)] + body;
      expect(body.padStart(v.deploy_token.body_len, "0"), c.token).toBe(c.body);
      expect(crc32(new TextEncoder().encode(`${v.deploy_token.prefix}${c.body}`)), c.token).toBe(c.crc32);
      expect(tokenChecksum(c.body), c.token).toBe(c.checksum);
      expect(tokenFromBody(c.body), c.token).toBe(c.token);
      expect(parseDeployToken(c.token), c.token).toEqual({ short: c.short });
      expect(await deployTokenHash(c.token), c.token).toBe(c.sha256);
    }
  });

  it("deploy tokens: reading one (the header's value, trimmed as HTTP trims it)", () => {
    expect(v.deploy_token.reads.some((c: any) => c.ok) && v.deploy_token.reads.some((c: any) => !c.ok)).toBe(true);
    for (const c of v.deploy_token.reads) {
      // The edge tells none of the refusals apart (one 401 invalid_token).
      expect(parseDeployToken(c.token.trim()), JSON.stringify(c.token)).toEqual(c.ok ? { short: c.short } : undefined);
    }
  });

  it("deploy tokens: a scope's ids, of either kind, trimmed, sorted, each once", () => {
    expect(v.deploy_token.scopes.some((c: any) => c.ok) && v.deploy_token.scopes.some((c: any) => !c.ok)).toBe(true);
    for (const c of v.deploy_token.scopes) {
      const read = readScopeIds(c.ids);
      if (c.ok) expect(read, JSON.stringify(c.ids)).toEqual(c.scope);
      else expect(read, JSON.stringify(c.ids)).toHaveProperty("error");
    }
  });

  it("template content hashes: the plugin's function, over a manifest that is no plugin's", async () => {
    for (const c of v.template_content_hash) {
      expect(await contentHash(json(c.manifest) as JsonObject, hashesOf(c.files)), c.name).toBe(c.hash);
    }
  });

  it("template packages: read as a device reads one, and as the store reads a token's publish", async () => {
    const read = async (raw: Uint8Array, signed: boolean) => {
      try {
        const t = await verifyTemplate(raw, undefined, signed);
        const left = new Set(t.ignored);
        // (`paths`: what a device installs; `ignored` what it leaves out, as the engine's map.)
        return {
          ok: true, id: t.id, version: t.version, key: t.key, hash: t.hash, sha256: t.sha256,
          files: t.files.size - t.ignored.length,
          paths: [...t.files.keys()].filter((p) => !left.has(p)).sort(compareUtf8), ignored: [...t.ignored].sort(compareUtf8)
        };
      } catch (e) {
        if (!(e instanceof PackageRefusal)) throw e;
        return { ok: false, error: e.code };
      }
    };
    expect(v.template_packages.length).toBeGreaterThan(0);
    for (const [i, c] of v.template_packages.entries()) {
      const raw = c.package_parts !== undefined ? new TextEncoder().encode(joinParts(rawVectors.template_packages[i].package_parts)) : fromB64(c.package_b64);
      // From a file or link, and from a device's own publish: signed.
      const fromDevice = await read(raw, true);
      expect(fromDevice.ok ? { ...fromDevice, version: undefined } : fromDevice, c.name).toEqual(c.result.ok ? { ...c.result, version: undefined } : c.result);
      if (c.result.ok && c.result.version !== undefined) expect((fromDevice as { version: string }).version, c.name).toBe(c.result.version);
      // As a token's: unsigned only. A device refuses a signed one under a
      // record naming no signer (`store_mismatch`); the store refuses it
      // first, as its publish says it (`bad_signature`). An unsigned one that
      // breaks no other rule is taken.
      const fromToken = await read(raw, false);
      if (c.store_result.ok) expect({ ...fromToken, version: undefined }, c.name).toEqual({ ...c.store_result, version: undefined });
      else if (c.store_result.error === "store_mismatch") expect(fromToken, c.name).toEqual({ ok: false, error: "bad_signature" });
      else expect(fromToken.ok, `${c.name}: ${JSON.stringify(c.store_result)}`).toBe(false);
    }
  });

  it("template listing rules", () => {
    for (const [i, c] of v.template_listing.entries()) {
      const written = rawVectors.template_listing[i].files_b64 as Record<string, unknown>;
      const files = new Map(Object.entries(c.files_b64 as Record<string, unknown>).map(([p, b]) => [p, fileBytes(b, written[p])]));
      const raw = json(c.manifest) as JsonObject;
      const { problems, warnings } = checkTemplate(raw, files, isText);
      const shape = (list: { rule: string; field: string | null; path: string | null; cause?: string; word?: string }[]) =>
        list.map((p) => ({ field: p.field, path: p.path, rule: p.rule, ...(p.cause === undefined ? {} : { cause: p.cause }), ...(p.word === undefined ? {} : { word: p.word }) }));
      expect(shape(problems), c.name).toEqual(c.problems);
      expect(shape(warnings), c.name).toEqual(c.warnings);
      if (problems.length === 0) {
        const kept = listingOfTemplate(raw, files);
        expect({
          categories: kept.categories, engines_zeron: kept.engines, homepage: kept.homepage,
          keywords: kept.keywords, license: kept.license, repository: kept.repository, screenshots: kept.screenshots
        }, c.name).toEqual(Object.fromEntries(Object.entries({ homepage: null, repository: null, license: null, ...c.listing })));
        expect(kept.icon).toBe("");
      }
    }
  }, 60_000);

  it("paths", () => {
    for (const c of v.paths) expect(plainPath(c.path), JSON.stringify(c.path)).toBe(c.ok);
  });

  it("manifests", () => {
    for (const c of v.manifests) {
      const m = readManifest(json(c.manifest) as JsonObject);
      expect(m.problem ?? null, c.name).toBe(c.problem);
      if ("id_error" in c) expect(idProblem(m.id) ?? null, c.name).toBe(c.id_error);
    }
  });

  it("semver: parse with its parts, order, compare, newer", () => {
    for (const c of v.semver.parse) {
      const p = parseVersion(c.input);
      expect(p !== undefined, JSON.stringify(c.input)).toBe(c.ok);
      if (p && c.ok) expect([p.major, p.minor, p.patch, p.pre.join("."), p.build.join(".")], c.input).toEqual([Number(c.major), Number(c.minor), Number(c.patch), c.pre, c.build]);
    }
    const order: string[] = v.semver.order;
    for (let i = 1; i < order.length; i++) expect(comparePrecedence(parseVersion(order[i - 1]!)!, parseVersion(order[i]!)!), `${order[i - 1]} < ${order[i]}`).toBe(-1);
    for (const c of v.semver.compare) expect(comparePrecedence(parseVersion(c.a)!, parseVersion(c.b)!), `${c.a} vs ${c.b}`).toBe(c.cmp);
    const corpus: string[] = v.semver.corpus_order ?? [];
    for (let i = 1; i < corpus.length; i++) expect(comparePrecedence(parseVersion(corpus[i - 1]!)!, parseVersion(corpus[i]!)!), `${corpus[i - 1]} < ${corpus[i]}`).toBe(-1);
    for (const c of v.newer) expect(comparePrecedence(parseVersion(c.candidate)!, parseVersion(c.installed)!) > 0, `${c.candidate} over ${c.installed}`).toBe(c.newer);
  });

  it("ranges", () => {
    for (const c of v.ranges) {
      const range = parseRange(c.range);
      if (c.error) expect(range, JSON.stringify(c.range)).toBeUndefined();
      else expect(range !== undefined && satisfies(parseVersion(c.version)!, range), `${c.version} in ${JSON.stringify(c.range)}`).toBe(c.matches);
    }
  });

  it("listing rules", () => {
    for (const [i, c] of v.listing.entries()) {
      const written = rawVectors.listing[i].files_b64 as Record<string, unknown>;
      const files = new Map(Object.entries(c.files_b64 as Record<string, string>).map(([p, b]) => [p, fileBytes(b, written[p])]));
      const manifest = readManifest(json(c.manifest) as JsonObject);
      const { problems, warnings } = checkListing(manifest, files, isText);
      // (A name's, description's or keywords' refusal says why, and where: listing_causes.)
      const shape = (list: { rule: string; field: string | null; path: string | null; cause?: string; word?: string }[]) =>
        list.map((p) => ({ field: p.field, path: p.path, rule: p.rule, ...(p.cause === undefined ? {} : { cause: p.cause }), ...(p.word === undefined ? {} : { word: p.word }) }));
      // One rule: the device's answer and the edge's are the same.
      expect(c, c.name).not.toHaveProperty("edge_problems");
      expect(shape(problems), c.name).toEqual(c.problems);
      expect(shape(warnings), c.name).toEqual(c.warnings);
      // What a listing that passes keeps: the fields as stored.
      if (problems.length === 0) {
        const kept = listingOf(manifest, files);
        expect("rule" in kept ? kept : {
          categories: kept.categories, engines_zeron: kept.engines, homepage: kept.homepage, icon: kept.icon,
          keywords: kept.keywords, license: kept.license, repository: kept.repository, screenshots: kept.screenshots
        }, c.name).toEqual(Object.fromEntries(Object.entries({ homepage: null, repository: null, license: null, engines_zeron: null, ...c.listing })));
      }
    }
  }, 60_000);

  it("changelog notes", () => {
    for (const c of v.changelog) expect(changelogNotes(c.changelog, c.version) ?? null, c.version).toBe(c.notes);
  });

  it("consent: each item, from the data file's tables", () => {
    expect([contained, fullControlNames, heldNames, windowsExtensions]).toEqual([
      STORE_DATA.consent.contained,
      STORE_DATA.consent.full_control,
      STORE_DATA.consent.held_to_its_own_rules,
      STORE_DATA.consent.windows_extensions
    ]);
    for (const c of v.consent_items) expect(consentItem(readManifest(json(c.manifest) as JsonObject)), c.name).toEqual(c.item);
  });
});
